css:
.crowdfilter-container {
    padding: 20px;
    background: radial-gradient(1200px 600px at 80% -10%, #2a1d54 0%, transparent 60%), linear-gradient(165deg, #0c0a1f 0%, #141033 55%, #1b1644 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e9e6fb;
}

.crowdfilter-header {
    background: linear-gradient(135deg, #4c1d95 0%, #6d28d9 45%, #1b1644 100%);
    color: #ffffff;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 14px 34px rgba(76,29,149,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.10);
}

.crowdfilter-header::before {
    content: '';
    position: absolute;
    top: -60%;
    left: -30%;
    width: 160%;
    height: 220%;
    background: radial-gradient(circle, rgba(251,191,36,0.10) 0%, transparent 55%);
    pointer-events: none;
}

.crowdfilter-header-icon {
    font-size: 2.7rem;
    margin-bottom: 8px;
}

.crowdfilter-header h1 {
    font-size: 1.95rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.4px;
}

.crowdfilter-header p {
    font-size: 1rem;
    opacity: 0.9;
    margin: 0 0 14px 0;
}

.crowdfilter-clock {
    display: inline-block;
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(255,255,255,0.2);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.3px;
}

.crowdfilter-clock #budgetDisplay {
    color: #fbbf24;
    font-weight: 800;
    margin: 0 4px;
}

.crowdfilter-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #b8b2e0;
    margin-bottom: 22px;
    font-weight: 600;
}

.crowdfilter-period-counter span {
    margin: 0 3px;
}

.crowdfilter-period-counter #currentDay,
.crowdfilter-period-counter #maxPeriods {
    color: #fbbf24;
    font-weight: 800;
}

.crowdfilter-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(109,40,217,0.3);
    border: 1px solid rgba(167,139,250,0.45);
    border-radius: 999px;
    color: #d7c9ff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.crowdfilter-kpi-section {
    margin-bottom: 22px;
}

.crowdfilter-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.crowdfilter-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.crowdfilter-kpi-card {
    background: linear-gradient(160deg, #211a47 0%, #181238 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.35);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.crowdfilter-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 12px 28px rgba(0,0,0,0.5);
}

.crowdfilter-kpi-hero {
    border: 1px solid rgba(251,191,36,0.4);
    background: linear-gradient(160deg, #2c2410 0%, #181238 100%);
}

.crowdfilter-kpi-label {
    font-size: 0.8rem;
    color: #a99fd6;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.crowdfilter-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.05;
}

.crowdfilter-kpi-hero .crowdfilter-kpi-value {
    color: #fbbf24;
    font-size: 3rem;
}

.crowdfilter-kpi-small .crowdfilter-kpi-value {
    font-size: 1.5rem;
}

.crowdfilter-kpi-sub {
    font-size: 0.74rem;
    color: #8b82b8;
    margin-top: 8px;
    line-height: 1.35;
}

.crowdfilter-kpi-bar-bg {
    height: 8px;
    background: rgba(255,255,255,0.1);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.crowdfilter-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.crowdfilter-capture-fill { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.crowdfilter-novelty-fill { background: linear-gradient(90deg, #7c3aed, #a78bfa); }

/* ---- Briefing ---- */
.crowdfilter-briefing {
    background: linear-gradient(160deg, #1d1742 0%, #181238 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 4px solid #fbbf24;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.35);
}

.crowdfilter-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #fbbf24;
}

.crowdfilter-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #d8d2f2;
}

.crowdfilter-briefing-text strong {
    color: #ffffff;
}

.crowdfilter-briefing-text em {
    color: #c9bcff;
    font-style: italic;
}

.crowdfilter-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(245,158,11,0.14);
    border: 1px solid rgba(245,158,11,0.45);
    border-radius: 10px;
    color: #ffe2ad;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.crowdfilter-controls {
    background: linear-gradient(160deg, #211a47 0%, #181238 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.35);
}

.crowdfilter-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #ffffff;
}

.crowdfilter-decisions-note {
    font-size: 0.86rem;
    color: #a99fd6;
    margin-bottom: 18px;
    font-style: italic;
}

.crowdfilter-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.crowdfilter-input-group {
    display: flex;
    flex-direction: column;
}

.crowdfilter-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #cfc8ee;
    margin-bottom: 7px;
}

.crowdfilter-container .form-control {
    background-color: #0f0b28;
    color: #f1eefc;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.crowdfilter-container .form-control:focus {
    border-color: #fbbf24;
    box-shadow: 0 0 0 3px rgba(251,191,36,0.2);
    background-color: #0f0b28;
    color: #f1eefc;
    outline: none;
}

.crowdfilter-container select.form-control {
    background-color: #0f0b28;
    color: #f1eefc;
}

.crowdfilter-container select.form-control option {
    background-color: #0f0b28;
    color: #f1eefc;
}

.crowdfilter-hint {
    font-size: 0.76rem;
    color: #8b82b8;
    margin-top: 6px;
    line-height: 1.4;
}

.crowdfilter-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.crowdfilter-container .btn-primary {
    background: linear-gradient(135deg, #6d28d9 0%, #a855f7 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 18px rgba(109,40,217,0.5);
}

.crowdfilter-container .btn-primary:hover {
    background: linear-gradient(135deg, #7c3aed 0%, #c084fc 100%);
}

.crowdfilter-container .btn-outline-secondary {
    color: #b8b2e0;
    border-color: rgba(255,255,255,0.25);
    border-radius: 10px;
}

.crowdfilter-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}

/* ---- Charts ---- */
.crowdfilter-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.crowdfilter-chart-box {
    background: #f6f4fd;
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.35);
    min-height: 320px;
}

/* ---- History ---- */
.crowdfilter-history {
    background: linear-gradient(160deg, #211a47 0%, #181238 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.35);
}

.crowdfilter-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffffff;
}

.crowdfilter-history table {
    color: #d8d2f2;
    margin-bottom: 0;
}

.crowdfilter-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.04);
}

.crowdfilter-history th {
    color: #a99fd6;
    border-color: rgba(255,255,255,0.12);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.crowdfilter-history td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .crowdfilter-container {
        padding: 12px;
    }
    .crowdfilter-header h1 {
        font-size: 1.5rem;
    }
    .crowdfilter-kpi-cards,
    .crowdfilter-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .crowdfilter-input-grid {
        grid-template-columns: 1fr;
    }
    .crowdfilter-charts {
        grid-template-columns: 1fr;
    }
    .crowdfilter-kpi-value {
        font-size: 2.1rem;
    }
    .crowdfilter-kpi-hero .crowdfilter-kpi-value {
        font-size: 2.4rem;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.cf-completion { padding: 8px 4px 4px; color: #e9e6f5; }
.cf-cm-head { text-align: center; margin-bottom: 18px; }
.cf-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #fbbf24; }
.cf-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #a78bfa; }
.cf-cm-grade { font-size: 1.25rem; font-weight: 700; margin-top: 6px; color: #f4f2fb; }
.cf-cm-platform { font-size: 0.9rem; margin-top: 6px; color: #c9c3e0; }
.cf-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0 18px; }
.cf-cm-metric { flex: 1 1 120px; min-width: 110px; background: rgba(124,58,237,0.14); border: 1px solid rgba(167,139,250,0.35); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cf-cm-mv { display: block; font-size: 1.45rem; font-weight: 800; color: #fbbf24; }
.cf-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #c9c3e0; text-transform: uppercase; letter-spacing: 0.03em; }
.cf-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #f4f2fb; }
.cf-cm-insights { margin: 0; padding-left: 20px; }
.cf-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #e3dff2; }

