            // gemMod modifies how many distant ideas survive the format; triageEase helps weak triage.
            this.FORMATS = {
                template: { gemMod: 0.70, triageEase: 0.18 },
                light:    { gemMod: 1.00, triageEase: 0.06 },
                free:     { gemMod: 1.15, triageEase: -0.06 }
            };

            // ---- Incentives & eligibility: who contributes and how distantly they reason ----
            this.INCENTIVES = {
