            };

            this.ROUNDS = [
                {
                    nameEn: 'Diagnose the Funnel',
                    nameEs: 'Diagnostique el Embudo',
                    briefingEn: `<strong>12 June 2026 — Aurena Group AG, Hamburg.</strong> Aurena (€2,600,000,000 revenue, 9,400 employees, 40 countries) runs <em>“Aurena Open,”</em> a public crowdsourcing platform with <strong>180,000 registered contributors</strong>. It is a strategic asset and a liability: a torrent of ideas your small review team cannot possibly read — and a documented habit of funding ideas that <em>“look like us”</em> while genuinely distant, category-breaking ideas drown unseen. The CEO just learned two of Aurena's biggest recent misses were crowd ideas the team passed over years ago.<br><br>The board's mandate is blunt: the next call must surface and <strong>fund at least one genuinely distant idea</strong>, backed by a <strong>€6,000,000</strong> development budget. The brutal arithmetic: the call will draw <strong>4,000 submissions</strong>; your team can deeply evaluate only <strong>120</strong> — <strong>3%</strong>. The research (Dahlander &amp; Piezunka) is clear: the bottleneck is not idea generation, it is <em>attention</em> — and default attention narrows toward the familiar.<br><br>First, before designing anything, fix your lens. <strong>Define what “distant” concretely means</strong> for Aurena across technology, category, user, and business-model distance. A multi-axis distance score is what later lets reviewers <em>see</em> novelty instead of scoring it down. A vague “overall quality” gut-feel is exactly how distant ideas die — they never look like quality to people who only know the core.`,
                    briefingEs: `<strong>12 de junio de 2026 — Aurena Group AG, Hamburgo.</strong> Aurena (€2.600.000.000 de ingresos, 9.400 empleados, 40 países) opera <em>“Aurena Open,”</em> una plataforma pública de crowdsourcing con <strong>180.000 contribuidores registrados</strong>. Es un activo estratégico y un lastre: un torrente de ideas que su pequeño equipo de revisión no puede leer — y el hábito documentado de financiar ideas que <em>“se parecen a nosotros”</em> mientras ideas genuinamente distantes y rompedoras se ahogan sin ser vistas. El CEO acaba de saber que dos de los mayores fracasos recientes de Aurena fueron ideas de la multitud que el equipo descartó años atrás.<br><br>El mandato del consejo es tajante: la próxima convocatoria debe surgir y <strong>financiar al menos una idea genuinamente distante</strong>, con un presupuesto de desarrollo de <strong>€6.000.000</strong>. La aritmética brutal: la convocatoria atraerá <strong>4.000 propuestas</strong>; su equipo solo puede evaluar a fondo <strong>120</strong> — el <strong>3%</strong>. La investigación (Dahlander y Piezunka) es clara: el cuello de botella no es generar ideas, es la <em>atención</em> — y la atención por defecto se estrecha hacia lo familiar.<br><br>Primero, antes de diseñar nada, fije su lente. <strong>Defina qué significa “distante”</strong> concretamente para Aurena en distancia de tecnología, categoría, usuario y modelo de negocio. Una puntuación de distancia multi-eje es lo que luego permite a los revisores <em>ver</em> la novedad en vez de penalizarla. Un vago instinto de “calidad general” es exactamente cómo mueren las ideas distantes — nunca parecen de calidad para quien solo conoce el núcleo.`,
                    eventEn: null,
                    eventEs: null
                },
                {
                    nameEn: 'Frame the Call',
                    nameEs: 'Formule la Convocatoria',
                    briefingEn: `Now <strong>design the crowdsourcing call</strong> — and remember that what comes in is decided here, at the very top of the funnel. Three levers shape the pile:<br><br><strong>Prompt framing.</strong> A narrow, on-brand prompt (“improve our home-care range”) returns 4,000 tidy, easy-to-review ideas — and almost no distant ones, because a breakthrough literally cannot enter. An open, provocative prompt (“solve the job; ignore our categories”) returns fewer, noisier submissions but far more genuinely distant ones. You can only capture distance you first let in.<br><strong>Submission format.</strong> A rigid template eases triage but crushes unconventional ideas into familiar boxes; free-form protects novelty but is harder to read.<br><strong>Incentives &amp; eligibility.</strong> Inviting only your existing community and rewarding “best fit” attracts near ideas; courting universities and adjacent industries with a novelty prize pulls in distant reasoning.<br><br>Each choice trades submission volume and triage difficulty against average novelty. Frame for the board's distant-idea goal, not for your team's comfort at the top of the funnel.`,
                    briefingEs: `Ahora <strong>diseñe la convocatoria de crowdsourcing</strong> — y recuerde que lo que entra se decide aquí, en lo más alto del embudo. Tres palancas moldean la pila:<br><br><strong>Encuadre del prompt.</strong> Un prompt estrecho y de marca (“mejore nuestra gama de cuidado del hogar”) devuelve 4.000 ideas ordenadas y fáciles de revisar — y casi ninguna distante, porque una idea rompedora literalmente no puede entrar. Un prompt abierto y provocador (“resuelva el trabajo; ignore nuestras categorías”) devuelve menos propuestas y más ruidosas, pero muchas más genuinamente distantes. Solo puede capturar la distancia que antes deja entrar.<br><strong>Formato de propuesta.</strong> Una plantilla rígida facilita el triaje pero aplasta ideas no convencionales en moldes familiares; el formato libre protege la novedad pero es más difícil de leer.<br><strong>Incentivos y elegibilidad.</strong> Invitar solo a su comunidad existente y premiar el “mejor encaje” atrae ideas cercanas; cortejar a universidades e industrias adyacentes con un premio a la novedad atrae razonamiento distante.<br><br>Cada elección cambia el volumen de propuestas y la dificultad de triaje frente a la novedad media. Encuadre para el objetivo de ideas distantes del consejo, no para la comodidad de su equipo en lo alto del embudo.`,
                    eventEn: `⚠️ <strong>Internal pressure:</strong> The community-management team warns that an open prompt will “triple the noise and we'll drown.” They are not wrong about volume — but a narrow prompt is exactly how the last two breakthroughs never even arrived.`,
                    eventEs: `⚠️ <strong>Presión interna:</strong> El equipo de gestión de comunidad advierte que un prompt abierto “triplicará el ruido y nos ahogaremos.” No se equivocan sobre el volumen — pero un prompt estrecho es exactamente cómo las dos últimas ideas rompedoras nunca llegaron a entrar.`
                },
                {
                    nameEn: 'Allocate Reviewer Attention',
                    nameEs: 'Asigne la Atención de Revisión',
                    briefingEn: `🌊 <strong>The submissions are in.</strong> Now the binding constraint bites: <strong>only 120 of the pile can be deeply reviewed</strong>. How you fill those 120 slots decides what survives.<br><br><strong>Crowd-vote ranking</strong> is cheap and scalable, but popularity rewards the familiar — slightly-better versions of products people already know. The genuinely distant ideas get a handful of votes and never make the cut.<br><strong>Reviewer cherry-pick</strong> is expert, but a homogeneous core-R&amp;D panel selects ideas that “look like real Aurena products” — narrow attention in action.<br><strong>Deliberate distance-aware allocation</strong> scores explicitly on your distance lens and protects attention for outliers.<br><br>Two further levers decide your capture rate: <strong>how many of the 120 slots you quarantine for distant outliers</strong> (reserve none and they drown statistically; the research is blunt about this), and <strong>who reviews</strong> — homogeneous experts narrow attention; a diverse panel has the absorptive capacity to recognise distant value. You will have to defend “wasting” review capacity on long shots. That is the point.`,
                    briefingEs: `🌊 <strong>Las propuestas están dentro.</strong> Ahora muerde la restricción vinculante: <strong>solo 120 de la pila pueden revisarse a fondo</strong>. Cómo llene esos 120 cupos decide qué sobrevive.<br><br><strong>El ranking por voto de la multitud</strong> es barato y escalable, pero la popularidad premia lo familiar — versiones algo mejores de productos que la gente ya conoce. Las ideas genuinamente distantes reciben un puñado de votos y nunca pasan el corte.<br><strong>La selección por revisores</strong> es experta, pero un panel homogéneo del núcleo de I+D elige ideas que “parecen productos Aurena reales” — atención estrecha en acción.<br><strong>La asignación deliberada consciente de la distancia</strong> puntúa explícitamente según su lente de distancia y protege atención para los atípicos.<br><br>Dos palancas más deciden su tasa de captura: <strong>cuántos de los 120 cupos reserva para atípicos distantes</strong> (no reserve ninguno y se ahogan estadísticamente; la investigación es contundente), y <strong>quién revisa</strong> — expertos homogéneos estrechan la atención; un panel diverso tiene la capacidad de absorción para reconocer valor distante. Tendrá que defender “malgastar” capacidad de revisión en apuestas lejanas. Ese es el punto.`,
                    eventEn: `📊 <strong>The reveal:</strong> The facilitator confirms the pile contains a handful of genuinely distant gems — including a refill-concentrate concept and a microbiome home-care platform. Under pure crowd-vote they each got 11 votes. Did your mechanism reserve any attention for them?`,
                    eventEs: `📊 <strong>La revelación:</strong> El facilitador confirma que la pila contiene un puñado de gemas genuinamente distantes — incluido un concepto de recarga-concentrado y una plataforma de cuidado del hogar basada en microbioma. Bajo voto puro de la multitud, cada una obtuvo 11 votos. ¿Su mecanismo reservó algo de atención para ellas?`
                },
                {
                    nameEn: 'Fund the Portfolio',
                    nameEs: 'Financie el Portafolio',
                    briefingEn: `🏛️ <strong>The funding meeting — you present to the board.</strong> Your shortlist holds a <strong>safe near idea</strong> (a credible €4,000,000 revenue case, low novelty) and at least one <strong>distant idea</strong> (€20,000,000 upside, high uncertainty, and a business-unit sponsor who is lukewarm). You hold <strong>€6,000,000</strong>.<br><br>Funding only the safe idea is defensible — and it is exactly the incremental pipeline the board asked you to fix; you ran a call to 180,000 people and funded the idea you could have had internally. Betting the whole budget unstaged on the moonshot is bold but stakes everything on an unvalidated concept with no internal champion. The discipline the research points to is <strong>real options</strong>: fund the near idea and buy a small <strong>pilot</strong> on the distant one — a stake that buys information before a large commitment.<br><br>And no distant idea survives the meeting without an owner. <strong>How hard will you work to win the lukewarm sponsor</strong> — brief them once, co-design the pilot, or make them the bet's executive owner? Capturing a distant idea in triage means nothing if it dies in this room. Present your portfolio and defend the novelty-versus-risk balance.`,
                    briefingEs: `🏛️ <strong>La reunión de financiación — presenta ante el consejo.</strong> Su lista corta tiene una <strong>idea cercana segura</strong> (un caso creíble de €4.000.000 de ingresos, baja novedad) y al menos una <strong>idea distante</strong> (€20.000.000 de potencial, alta incertidumbre, y un patrocinador de unidad de negocio tibio). Dispone de <strong>€6.000.000</strong>.<br><br>Financiar solo la idea segura es defendible — y es exactamente la cartera incremental que el consejo le pidió arreglar; lanzó una convocatoria a 180.000 personas y financió la idea que podía tener internamente. Apostar todo el presupuesto sin escalonar al moonshot es audaz pero lo arriesga todo en un concepto no validado y sin campeón interno. La disciplina que señala la investigación son las <strong>opciones reales</strong>: financie la idea cercana y compre un pequeño <strong>piloto</strong> en la distante — una apuesta que compra información antes de un gran compromiso.<br><br>Y ninguna idea distante sobrevive a la reunión sin un dueño. <strong>¿Cuánto trabajará para ganarse al patrocinador tibio</strong> — informarle una vez, co-diseñar el piloto, o hacerle dueño ejecutivo de la apuesta? Capturar una idea distante en el triaje no significa nada si muere en esta sala. Presente su portafolio y defienda el balance novedad-riesgo.`,
                    eventEn: `🎙️ <strong>The board asks:</strong> “If two real breakthroughs already died in this queue once, what stops it happening a third time — and why should we keep paying €4,000,000 a year for the platform?” Your funding choice IS your answer.`,
                    eventEs: `🎙️ <strong>El consejo pregunta:</strong> “Si dos avances reales ya murieron en esta cola una vez, ¿qué impide que pase una tercera — y por qué deberíamos seguir pagando €4.000.000 al año por la plataforma?” Su elección de financiación ES su respuesta.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    captureRate: 4,        // distant-idea capture rate (%) — default funnel ~4%
                    avgNovelty: 0,         // avg novelty/distance of the reviewed pool (0-100)
                    reviewed: 0,           // suggestions deeply reviewed (cap 120)
                    innovationValue: 0,    // risk-adjusted expected EUR value of funded portfolio (M)
                    submissions: 4000,     // submissions received
                    gemsInPile: 0,         // distant gems that entered the pile (after framing)
                    gemsCaptured: 0,       // distant gems that reached deep review
                    budgetAllocated: 0,    // EUR M committed
                    platform: 'atrisk',    // 'atrisk' | 'saved' | 'cut'
                    mandateMet: false,     // funded >=1 distant idea
                    sponsorWon: false,
                    captureHistory: [],
                    noveltyHistory: [],
                    valueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    lens: 2,
                    framing: 'balanced',
                    format: 'light',
                    incentive: 'reach',
                    triage: 'deliberate',
                    reserved: 30,
                    panel: 'mixed',
                    funding: 'staged',
                    sponsor: 3
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var lensEl = document.getElementById('lensInput');
            var framingEl = document.getElementById('framingInput');
            var formatEl = document.getElementById('formatInput');
            var incentiveEl = document.getElementById('incentiveInput');
            var triageEl = document.getElementById('triageInput');
            var reservedEl = document.getElementById('reservedInput');
            var panelEl = document.getElementById('panelInput');
            var fundingEl = document.getElementById('fundingInput');
            var sponsorEl = document.getElementById('sponsorInput');

            if (lensEl) decisions.lens = parseInt(lensEl.value, 10);
            if (framingEl) decisions.framing = framingEl.value;
            if (formatEl) decisions.format = formatEl.value;
            if (incentiveEl) decisions.incentive = incentiveEl.value;
            if (triageEl) decisions.triage = triageEl.value;
            if (reservedEl) decisions.reserved = parseInt(reservedEl.value, 10);
            if (panelEl) decisions.panel = panelEl.value;
            if (fundingEl) decisions.funding = fundingEl.value;
            if (sponsorEl) decisions.sponsor = parseInt(sponsorEl.value, 10);

            if (!Number.isFinite(decisions.lens) || decisions.lens < 0 || decisions.lens > 4) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('lens_warning'), 'warning');
                return false;
            }
            if (!this.FRAMINGS[decisions.framing]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('framing_warning'), 'warning');
                return false;
            }
            if (!this.FORMATS[decisions.format]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('format_warning'), 'warning');
                return false;
            }
            if (!this.INCENTIVES[decisions.incentive]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('incentive_warning'), 'warning');
                return false;
            }
            if (!this.TRIAGE[decisions.triage]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('triage_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.reserved) || decisions.reserved < 0 || decisions.reserved > 120) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('reserved_warning'), 'warning');
                return false;
            }
            if (!this.PANELS[decisions.panel]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('panel_warning'), 'warning');
                return false;
            }
            if (['safe', 'moonshot', 'split', 'staged'].indexOf(decisions.funding) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('funding_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.sponsor) || decisions.sponsor < 1 || decisions.sponsor > 5) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('sponsor_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        // ---- Pure helper: compute the funnel from the current decision set. ----
        // Returns the full snapshot so every round shows the consequence of the
        // levers committed so far (the funnel is cumulative, evaluated end-to-end).
        _computeFunnel(d) {
            var framing = this.FRAMINGS[d.framing];
            var format = this.FORMATS[d.format];
            var incentive = this.INCENTIVES[d.incentive];
            var triage = this.TRIAGE[d.triage];
            var panel = this.PANELS[d.panel];
            var lensNorm = d.lens / 4; // 0..1 quality of the distance lens

            // ---- Gate A: how many distant gems ENTER the pile (framing × format × incentive) ----
            var gemFactor = framing.gemFactor * format.gemMod * incentive.gemMod;
            gemFactor = Math.max(0, Math.min(1, gemFactor));
            var gemsInPile = Math.max(0, Math.round(this.TRUE_GEMS * gemFactor));

            // Submissions received (flavour) and noise level for triage difficulty.
            var submissions = framing.volume;

            // ---- Gate B: of the gems in the pile, what fraction the 120 slots surface ----
            // Base capture by mechanism, lifted by reserved slots (only if the lens can recognise
            // distance) and by panel diversity (absorptive capacity). Noise penalises weak triage.
            var reservedShare = d.reserved / this.REVIEW_CAP; // 0..1 of the 120 quarantined
            // Reserved attention only WORKS if you have a lens to score distance AND a mechanism
            // willing to use it. A crowd-vote funnel can't honour reserved slots much.
            var reservedLift = reservedShare * triage.reservedEff * (0.35 + 0.65 * lensNorm);

            // Diminishing returns: quarantining ALL 120 wastes capacity on too few real gems.
            if (reservedShare > 0.5) {
                reservedLift -= (reservedShare - 0.5) * 0.25;
            }

            var noisePenalty = framing.noise * (1 - triage.baseCapture) * 0.20;

            var captureFrac = triage.baseCapture + reservedLift;
            captureFrac = captureFrac * panel.recognise;
            captureFrac = captureFrac - noisePenalty;
            // The distance lens itself raises the ceiling: without a lens, even a good mechanism
            // can only recognise so much distance.
            captureFrac = captureFrac * (0.55 + 0.45 * lensNorm);
            captureFrac = Math.max(0.02, Math.min(1, captureFrac));

            var gemsCaptured = Math.min(gemsInPile, Math.round(gemsInPile * captureFrac + 0.0001));
            // Capture RATE is measured against the gems that exist in the world (TRUE_GEMS),
            // so a narrow call that never let gems in still scores a low capture rate.
            var captureRate = Math.round((gemsCaptured / this.TRUE_GEMS) * 100);

            // ---- Average novelty of the 120-idea reviewed pool ----
            // Driven by what entered (framing/incentive) and whether triage sought distance.
            var poolNovelty = 100 * (
                0.45 * framing.gemFactor +
                0.20 * (incentive.gemMod - 0.65) / 0.65 +
                0.25 * (triage.baseCapture + reservedLift) +
                0.10 * lensNorm
            );
            // Rigid templates flatten novelty even when distant ideas slipped in.
            poolNovelty = poolNovelty * (d.format === 'template' ? 0.8 : 1.0);
            var avgNovelty = Math.max(0, Math.min(100, Math.round(poolNovelty)));

            var reviewed = this.REVIEW_CAP;

            return {
                gemsInPile: gemsInPile,
                gemsCaptured: gemsCaptured,
                captureRate: captureRate,
                avgNovelty: avgNovelty,
                reviewed: reviewed,
                submissions: submissions,
                captureFrac: captureFrac
            };
        }

        // ---- Pure helper: convert a captured funnel into funded innovation value. ----
        _computeFunding(d, funnel) {
            var sponsorNorm = (d.sponsor - 1) / 4; // 0..1
            var distantAvailable = funnel.gemsCaptured > 0;

            var budgetAllocated = 0;
            var nearValue = 0;       // expected EUR M from the near idea
            var distantValue = 0;    // risk-adjusted expected EUR M from the distant idea
            var mandateMet = false;

            // Probability the distant bet pays off rises with a pilot (real options) and a strong sponsor.
            // Sponsor only matters if a distant idea was actually captured to fund.
            var sponsorWon = distantAvailable && sponsorNorm >= 0.5;

            if (d.funding === 'safe') {
                // All €6M into the near idea. Defensible, defeats the mandate.
                budgetAllocated = this.DEV_BUDGET;
                nearValue = this.NEAR_CASE; // ~€4M case fully funded
                mandateMet = false;
            } else if (d.funding === 'moonshot') {
                // All €6M unstaged into the distant idea — high variance, no near idea funded.
                budgetAllocated = this.DEV_BUDGET;
                if (distantAvailable) {
                    var pMoon = 0.18 + 0.32 * sponsorNorm; // no pilot info; sponsor de-risks execution
                    distantValue = this.DISTANT_UPSIDE * pMoon - 6 * (1 - pMoon); // burn risk
                    mandateMet = true;
                } else {
                    // You bet the budget on a moonshot you never actually captured in triage.
                    distantValue = -3;
                    mandateMet = false;
                }
            } else if (d.funding === 'split') {
                // Fully fund both at once: near (€4M) + distant unpiloted (~€2M committed).
                budgetAllocated = this.DEV_BUDGET;
                nearValue = this.NEAR_CASE * 0.85; // squeezed
                if (distantAvailable) {
                    var pSplit = 0.20 + 0.30 * sponsorNorm;
                    distantValue = this.DISTANT_UPSIDE * 0.6 * pSplit; // under-funded upside
                    mandateMet = true;
                }
            } else { // staged
                // Near idea funded + a piloted distant bet (real options). Best risk-adjusted play.
                budgetAllocated = this.DEV_BUDGET;
                nearValue = this.NEAR_CASE * 0.9;
                if (distantAvailable) {
                    var pStaged = 0.40 + 0.40 * sponsorNorm; // pilot buys information
                    distantValue = this.DISTANT_UPSIDE * 0.7 * pStaged; // staged: capped but de-risked
                    mandateMet = true;
                }
            }

            var innovationValue = Math.round((nearValue + distantValue) * 10) / 10;

            return {
                budgetAllocated: budgetAllocated,
                innovationValue: innovationValue,
                mandateMet: mandateMet,
                sponsorWon: sponsorWon
            };
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            // The funnel is evaluated end-to-end from all levers committed so far. Early rounds
            // show a provisional read (later levers at their current/default values); the final
            // round locks in the funding consequence.
            var funnel = this._computeFunnel(d);

            ds.gemsInPile = funnel.gemsInPile;
            ds.gemsCaptured = funnel.gemsCaptured;
            ds.captureRate = funnel.captureRate;
            ds.avgNovelty = funnel.avgNovelty;
            ds.submissions = funnel.submissions;
            // Suggestions are only "deeply reviewed" once the call has run and triage is set (R3+).
            ds.reviewed = period >= 3 ? funnel.reviewed : 0;

            // Funding consequence resolves at Round 4 (the funding meeting).
            if (period >= 4) {
                var funding = this._computeFunding(d, funnel);
                ds.budgetAllocated = funding.budgetAllocated;
                ds.innovationValue = funding.innovationValue;
                ds.mandateMet = funding.mandateMet;
                ds.sponsorWon = funding.sponsorWon;

                // Platform fate: the board keeps "Aurena Open" only if the call met the mandate
                // with real captured novelty; a failed call threatens the €4M/yr platform.
                if (funnel.captureRate >= 38 && ds.mandateMet) {
                    ds.platform = 'saved';
                } else if (funnel.captureRate < 13 || (!ds.mandateMet && ds.innovationValue <= this.NEAR_CASE)) {
                    ds.platform = 'cut';
                } else {
                    ds.platform = 'atrisk';
                }
            } else {
                ds.budgetAllocated = 0;
                ds.platform = 'atrisk';
                // Show a provisional projected value so the KPI is alive before funding.
                var projected = this._computeFunding(d, funnel);
                ds.innovationValue = Math.round(projected.innovationValue * 10) / 10;
            }

            // History (capture + novelty + value trajectory across rounds).
            ds.captureHistory.push(ds.captureRate);
            ds.noveltyHistory.push(ds.avgNovelty);
            ds.valueHistory.push(ds.innovationValue);

            // Expose composite to reporting/grading layer every period (results_utils.php
            // reads domainState.performance.overallScore). Round 4 locks the final score.
            ds.performance = { overallScore: this._composite({
                captureRate: ds.captureRate, avgNovelty: ds.avgNovelty,
                innovationValue: ds.innovationValue, mandateMet: ds.mandateMet,
                platform: ds.platform
            }) };

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return {
                period: period,
