        // ---- Shared composite score (0-100). Single source of truth for BOTH the
        // per-round score written to domainState.performance.overallScore (reporting layer)
        // AND the final debrief score. Weights unchanged from v1.0.0. ----
        _composite(v) {
            var capture = Math.min(100, v.captureRate || 0);
            var novelty = Math.min(100, v.avgNovelty || 0);
            var value = v.innovationValue || 0;
            var captureScore = capture * 0.35;
            var noveltyScore = novelty * 0.20;
            var valueScore = Math.max(0, Math.min(100, (value / 16) * 100)) * 0.30;
            var mandateScore = (v.mandateMet ? 100 : 0) * 0.15;
            var total = Math.round(captureScore + noveltyScore + valueScore + mandateScore);
            if (v.platform === 'saved') total = Math.min(100, total + 6);
            if (v.platform === 'cut') total = Math.max(0, total - 10);
            return Math.max(0, Math.min(100, total));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var capture = r.captureRate || 0;
            var novelty = r.avgNovelty || 0;
            var value = r.innovationValue || 0;
            var mandateMet = !!r.mandateMet;
            var gemsCaptured = r.gemsCaptured || 0;

            // Composite score via the shared helper (weights unchanged from v1.0.0).
            var totalScore = this._composite({
                captureRate: capture, avgNovelty: novelty, innovationValue: value,
                mandateMet: mandateMet, platform: r.platform
            });

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            var performanceKey = 'grade_local';
            if (totalScore >= 80 && mandateMet && capture >= 50) performanceKey = 'grade_architect';
            else if (totalScore >= 64) performanceKey = 'grade_allocator';
            else if (totalScore >= 46) performanceKey = 'grade_developing';
            var performance = T(performanceKey);

            var insights = [];
            var framings = history.map(function(h) { return h.results && h.results.framing; });
            insights.push(framings.indexOf('narrow') !== -1 ? T('ins_framing_narrow') : T('ins_framing_open'));
            if (r.triage === 'crowd') insights.push(T('ins_triage_crowd'));
            else if (r.triage === 'expert') insights.push(T('ins_triage_expert'));
            else insights.push(T('ins_triage_deliberate'));
            var maxReserved = history.reduce(function(m, h) { return Math.max(m, (h.results && h.results.reserved) || 0); }, 0);
            if (maxReserved === 0) insights.push(T('ins_reserved_none'));
            else insights.push(T('ins_reserved_some', { n: maxReserved }));
            if (r.panel === 'homogeneous') insights.push(T('ins_panel_homogeneous'));
            else if (r.panel === 'diverse') insights.push(T('ins_panel_diverse'));
            if (r.funding === 'safe') insights.push(T('ins_funding_safe'));
            else if (r.funding === 'moonshot') insights.push(T('ins_funding_moonshot'));
            else if (r.funding === 'staged') insights.push(T('ins_funding_staged'));
            if (gemsCaptured > 0 && !r.sponsorWon && (r.funding === 'staged' || r.funding === 'split' || r.funding === 'moonshot')) {
                insights.push(T('ins_sponsor_undone'));
            }
            if (r.platform === 'saved') insights.push(T('ins_platform_saved'));
            else if (r.platform === 'cut') insights.push(T('ins_platform_cut'));

            return {
                totalScore: totalScore,
                overallScore: totalScore,
                captureRate: capture,
                avgNovelty: novelty,
                innovationValue: value,
                gemsCaptured: gemsCaptured,
                gemsInPile: r.gemsInPile || 0,
                mandateMet: mandateMet,
                platform: r.platform,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore : 0;
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var value = Math.round((s.innovationValue || 0) * 10) / 10;
            var valueStr = (value < 0 ? '\u2212\u20ac' + Math.abs(value) + 'M' : '\u20ac' + value + 'M');
            var platform = s.platform === 'saved' ? T('platform_saved')
                : (s.platform === 'cut' ? T('platform_cut') : T('platform_atrisk'));
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="cf-cm-metric"><span class="cf-cm-mv">' + (s.captureRate || 0) + '%</span><span class="cf-cm-ml">' + T('cm_m_capture') + '</span></div>'
                + '<div class="cf-cm-metric"><span class="cf-cm-mv">' + (s.avgNovelty || 0) + '</span><span class="cf-cm-ml">' + T('cm_m_novelty') + '</span></div>'
                + '<div class="cf-cm-metric"><span class="cf-cm-mv">' + valueStr + '</span><span class="cf-cm-ml">' + T('cm_m_value') + '</span></div>'
                + '<div class="cf-cm-metric"><span class="cf-cm-mv">' + (s.gemsCaptured || 0) + '/' + (s.gemsInPile || 0) + '</span><span class="cf-cm-ml">' + T('cm_m_gems') + '</span></div>';
            return ''
                + '<div class="cf-completion">'
                +   '<div class="cf-cm-head">'
                +     '<div class="cf-cm-score">' + score + '<span class="cf-cm-score-max">/100</span></div>'
                +     '<div class="cf-cm-grade">' + grade + '</div>'
                +     '<div class="cf-cm-platform">' + T('platform_label') + ': <strong>' + platform + '</strong></div>'
                +   '</div>'
                +   '<div class="cf-cm-metrics">' + metrics + '</div>'
                +   '<div class="cf-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="cf-cm-insights">' + items + '</ul>'
                + '</div>';
        }

