            if (results.framing === 'narrow') return window.mySimulation.t('hint_narrow');
            if (results.triage === 'crowd') return window.mySimulation.t('hint_crowdvote');
            if (results.triage === 'expert' && results.panel === 'homogeneous') return window.mySimulation.t('hint_homogeneous');
            if (results.reserved === 0 && state.currentPeriod >= 3) return window.mySimulation.t('hint_noreserve');
            if (state.currentPeriod >= 4 && results.funding === 'safe') return window.mySimulation.t('hint_fundsafe');
            if (state.currentPeriod >= 4 && results.funding === 'moonshot') return window.mySimulation.t('hint_fundmoonshot');
